function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 2 || matrix.length > 250) return 'matrix needs 2 to 250 rows.';
  const n = matrix.length;
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== n) return 'matrix must be square (n rows of n values).';
    if (row.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is an integer between -100000 and 100000.';
  }
  return null;
}

