function maxMatrixSum(matrix) {
  let total = 0;
  let negatives = 0;
  let smallest = Infinity;

  for (const row of matrix) {
    for (const value of row) {
      total += Math.abs(value);
      if (value < 0) {
        negatives++;
      }
      smallest = Math.min(smallest, Math.abs(value));
    }
  }

  if (negatives % 2 === 1) {
    total -= 2 * smallest;
  }
  return total;
}

