function maxMatrixSum(matrix) {
  // Breadth-first search over every sign pattern reachable by the moves.
  const n = matrix.length;
  const cells = n * n;
  const values = matrix.flat();
  const pairs = [];
  for (let r = 0; r < n; r++)
    for (let c = 0; c < n; c++) {
      if (c + 1 < n) pairs.push((1 << (r * n + c)) | (1 << (r * n + c + 1)));
      if (r + 1 < n) pairs.push((1 << (r * n + c)) | (1 << ((r + 1) * n + c)));
    }
  const seen = new Set([0]);
  const queue = [0];
  let best = -Infinity;
  while (queue.length) {
    const mask = queue.shift();
    let sum = 0;
    for (let i = 0; i < cells; i++) sum += (mask >> i) & 1 ? -values[i] : values[i];
    best = Math.max(best, sum);
    for (const pair of pairs) {
      const next = mask ^ pair;
      if (!seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return best;
}

