function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 2 + Math.floor(rand() * 2);
  const span = size === 'large' ? 100000 : (rand() < 0.5 ? 5 : 100000);
  const negativeShare = rand();
  const matrix = [];
  for (let r = 0; r < n; r++) {
    const row = [];
    for (let c = 0; c < n; c++) {
      const magnitude = Math.floor(rand() * (span + 1));
      row.push(rand() < negativeShare ? -magnitude : magnitude);
    }
    matrix.push(row);
  }
  return [matrix];
}
